.status-time-range-card {
  border: 1px solid var(--c6);
  background: linear-gradient(180deg, #fcfffc 0%, #f4faf5 100%);
  padding: 10px 12px 14px;
  margin: -2px 0 10px;
}

.status-time-range-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 10px;
}

.status-time-range-header strong {
  display: block;
  font-size: 13px;
  color: var(--c2);
}

.status-time-range-summary {
  display: inline-block;
  margin-top: 2px;
  font-size: 12px;
  color: var(--c4);
}

.status-time-range-chips {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 6px;
}

.status-time-range-chip {
  --slot-color: #66bb6a;
  display: inline-flex;
  align-items: center;
  padding: 3px 8px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 600;
  color: color-mix(in srgb, var(--slot-color) 60%, #1f1f1f 40%);
  background: color-mix(in srgb, var(--slot-color) 16%, #ffffff 84%);
  border: 1px solid color-mix(in srgb, var(--slot-color) 28%, #d7e1d9 72%);
}

.status-time-range-track {
  position: relative;
  height: 72px;
}

.status-time-range-base {
  position: absolute;
  left: 0;
  right: 0;
  top: 26px;
  height: 10px;
  border-radius: 999px;
  background:
    linear-gradient(90deg, #f3faf4 0 50%, #eef7f1 50% 70.833%, #eef1fa 70.833% 100%);
  border: 1px solid var(--c7);
}

.status-time-range-fill {
  --slot-color: #66bb6a;
  position: absolute;
  top: 26px;
  height: 10px;
  border-radius: 999px;
  background: linear-gradient(90deg, color-mix(in srgb, var(--slot-color) 85%, #ffffff 15%), var(--slot-color));
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--slot-color) 45%, #ffffff 55%);
}

.status-time-range-slot-label {
  position: absolute;
  top: 6px;
  transform: translateX(-50%);
  font-size: 11px;
  font-weight: 600;
  color: var(--c4);
  white-space: nowrap;
}

.status-time-range-marker {
  position: absolute;
  top: 20px;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 22px;
}

.status-time-range-marker::before {
  content: '';
  display: block;
  width: 1px;
  height: 26px;
  background: var(--c6);
}

.status-time-range-marker.is-event::before {
  background: #d97c2b;
  border-left: 1px dashed #d97c2b;
}

.status-time-range-event {
  position: absolute;
  top: -18px;
  padding: 1px 6px;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 700;
  color: #9a4e10;
  background: #fff2e2;
  border: 1px solid #f1c596;
  white-space: nowrap;
}

.status-time-range-time {
  position: absolute;
  top: 38px;
  font-size: 10px;
  color: var(--c5);
  white-space: nowrap;
}

@media (max-width: 720px) {
  .status-time-range-header {
    flex-direction: column;
  }

  .status-time-range-chips {
    justify-content: flex-start;
  }

  .status-time-range-track {
    height: 82px;
  }
}

